node -e '
const { deliver } = require("/workspace/src/dispatcher.js");

async function run(name, io) {
  try {
    const res = await deliver(io, { id: "evt-1", type: "ping" });
    console.log(name, "-> resolved", JSON.stringify(res), "calls:", io.calls);
  } catch (e) {
    console.log(name, "-> threw", e.message, "calls:", io.calls);
  }
}

(async () => {
  // 1. Two 502s then success
  let io1 = { calls: 0, post: async (p, b, o) => { io1.calls++; if (io1.calls <= 2) return { status: 502 }; console.log("headers on success call:", JSON.stringify(o)); return { status: 200 }; } };
  await run("502x2-then-200", io1);

  // 2. Network error then success
  let io2 = { calls: 0, post: async (p, b, o) => { io2.calls++; if (io2.calls === 1) throw new Error("ECONNREFUSED"); return { status: 200 }; } };
  await run("network-err-then-200", io2);

  // 3. Always 502 -> throws after max retries
  let io3 = { calls: 0, post: async () => { io3.calls++; return { status: 502 }; } };
  await run("always-502", io3);

  // 4. 400 -> no retry, returned
  let io4 = { calls: 0, post: async () => { io4.calls++; return { status: 400 }; } };
  await run("400-no-retry", io4);

  // 5. Thrown 404 -> no retry
  let io5 = { calls: 0, post: async () => { io5.calls++; const e = new Error("Not Found"); e.status = 404; throw e; } };
  await run("thrown-404", io5);

  // 6. Thrown 502 -> retried then success
  let io6 = { calls: 0, post: async () => { io6.calls++; if (io6.calls === 1) { const e = new Error("Bad Gateway"); e.status = 502; throw e; } return { status: 200 }; } };
  await run("thrown-502-then-200", io6);
})();
' 2>&1

